const body = $json || {};
const action = String(body.action || 'health').toLowerCase();

if (action === 'health') {
  return [{ json: {
    status: 'ok',
    service: 'EMMA_N8N_API_BRIDGE',
    capabilities: ['health', 'echo', 'workflow_stats', 'help'],
    timestamp: new Date().toISOString()
  } }];
}

if (action === 'echo') {
  return [{ json: {
    status: 'ok',
    action,
    payload: body.payload ?? null,
    note: 'EMMA kann über n8n externe HTTP-Tools nutzen (Internet/Bilder), wenn die Nodes verbunden sind.'
  } }];
}

if (action === 'workflow_stats') {
  const summary = {
    requestedBy: body.user || 'unknown',
    requestedAt: new Date().toISOString(),
    hint: 'Verbinde diesen Endpoint mit n8n API Calls oder DB-Layer für Live-Stats.',
    checks: [
      'n8n /rest/health',
      'n8n /api/v1/workflows',
      'n8n /api/v1/executions?status=error'
    ]
  };
  return [{ json: { status: 'ok', action, summary } }];
}

if (action === 'help') {
  return [{ json: {
    status: 'ok',
    action,
    commands: {
      status: 'action=workflow_stats',
      ping: 'action=health',
      echo: 'action=echo + payload'
    },
    telegramReplyTemplate: 'Status: /status /health /diag verfügbar. Internet/Bilder gehen nur wenn HTTP- und OCR/Vision-Nodes im Workflow aktiv verbunden sind.'
  } }];
}

return [{ json: {
  status: 'error',
  reason: 'unsupported_action',
  supported: ['health', 'echo', 'workflow_stats', 'help']
} }];
